<?php

declare(strict_types=1);

namespace Runalyze\Model\EquipmentType;

/**
 * Generated by hand
 */
final class EntityTest extends \PHPUnit\Framework\TestCase
{
    public function testSimpleObject(): void
    {
        $Type = new Entity([
            Entity::NAME => 'Equipment type name',
            Entity::INPUT => 1,
            Entity::MAX_KM => 100,
            Entity::MAX_TIME => 0,
        ]);

        $this->assertSame('Equipment type name', $Type->name());
        $this->assertTrue($Type->allowsMultipleValues());
        $this->assertTrue($Type->hasMaxDistance());
        $this->assertEquals(100, $Type->maxDistance());
        $this->assertFalse($Type->hasMaxDuration());
        $this->assertSame(0, $Type->maxDuration());
    }
}
